class Solution {
    int gcdInt(int a, int b) {
        while (b) { int t = a % b; a = b; b = t; }
        return a;
    }
public:
    int resilientSubarray(vector<int>& nums, int k) {
        int n = nums.size(), ans = 1;
        for (int i = 0; i < n;) {
            int j = i, r = nums[i] % k;
            while (j < n && nums[j] % k == r) ++j;
            int len = j - i, period = k / gcdInt(k, r);
            int best = 1 + ((len - 1) / period) * period;
            ans = max(ans, best);
            i = j;
        }
        return ans;
    }
};
